package com.bobbyesp.spowlo.utils

import android.content.Context
import android.database.sqlite.SQLiteDatabase
import android.util.Log
import android.webkit.CookieManager
import com.bobbyesp.spowlo.utils.FilesUtil.getCookiesFile
import java.io.File

private const val CHROMIUM_EPOCH_OFFSET_SECONDS = 11_644_473_600L

private const val COOKIE_FILE_HEADER = "# Netscape HTTP Cookie File\n" +
    "# Auto-generated by Spowlo from the built-in YouTube sign-in\n"

private const val TAG = "CookieExport"

// yt-dlp only needs the account cookies YouTube and Google set.
private val YOUTUBE_DOMAINS = listOf(
    "youtube.com",
    "youtube-nocookie.com",
    "googlevideo.com",
    "google.com",
)

private const val COOKIE_QUERY =
    "select host_key, name, value, path, expires_utc, is_secure, is_httponly from cookies"

/** Writes the WebView's YouTube and Google cookies for yt-dlp. */
fun Context.exportYoutubeCookies(): Result<Int> = runCatching {
    CookieManager.getInstance().flush()
    val cookies = readYoutubeCookies()
    val content = buildString {
        append(COOKIE_FILE_HEADER)
        cookies.forEach { append(it.toNetscapeLine()).append('\n') }
    }
    FilesUtil.writeContentToFile(content, getCookiesFile())
    Log.d(TAG, "Exported ${cookies.size} cookies for yt-dlp")
    cookies.size
}

fun Context.hasSavedYoutubeCookies(): Boolean = runCatching {
    val file = getCookiesFile()
    file.isFile && file.useLines { lines -> lines.any { it.contains("youtube.com") } }
}.getOrDefault(false)

/** Signs the WebView out of YouTube without touching the Spotify web-player session. */
fun Context.clearYoutubeCookies(): Result<Unit> = runCatching {
    val cookies = readYoutubeCookies()
    val cookieManager = CookieManager.getInstance()
    cookies.forEach { cookie ->
        val url = "https://${cookie.host.removePrefix(".")}${cookie.path}"
        val attributes = buildString {
            append("${cookie.name}=; Max-Age=0; Path=${cookie.path}")
            if (cookie.host.startsWith(".")) append("; Domain=${cookie.host}")
            if (cookie.secure) append("; Secure")
        }
        cookieManager.setCookie(url, attributes)
    }
    cookieManager.flush()
    getCookiesFile().delete()
}

private fun Context.readYoutubeCookies(): List<StoredCookie> {
    val database = chromiumCookieDatabase() ?: run {
        Log.d(TAG, "WebView cookie database not found")
        return emptyList()
    }

    var lastError: Throwable? = null
    repeat(3) { attempt ->
        try {
            return readCookies(database)
        } catch (error: Exception) {
            lastError = error
            if (attempt < 2) Thread.sleep(150)
        }
    }
    throw lastError ?: IllegalStateException("Unable to read WebView cookies")
}

private fun readCookies(database: File): List<StoredCookie> =
    SQLiteDatabase.openDatabase(database.path, null, SQLiteDatabase.OPEN_READONLY).use { db ->
        db.rawQuery(COOKIE_QUERY, null).use { cursor ->
            val cookies = mutableListOf<StoredCookie>()
            while (cursor.moveToNext()) {
                val host = cursor.getString(0)
                if (!host.isYoutubeDomain()) continue
                val expiresUtc = cursor.getLong(4)
                cookies += StoredCookie(
                    host = host,
                    name = cursor.getString(1),
                    value = cursor.getString(2),
                    path = cursor.getString(3),
                    expiresUtc = expiresUtc,
                    secure = cursor.getLong(5) == 1L,
                    httpOnly = cursor.getLong(6) == 1L,
                )
            }
            cookies
        }
    }

private fun String.isYoutubeDomain(): Boolean {
    val host = removePrefix(".")
    return YOUTUBE_DOMAINS.any { domain -> host == domain || host.endsWith(".$domain") }
}

private fun Long.toExpirySeconds(): Long = this / 1_000_000L - CHROMIUM_EPOCH_OFFSET_SECONDS

private fun StoredCookie.toNetscapeLine(): String {
    val includeSubdomains = if (host.startsWith(".")) "TRUE" else "FALSE"
    val expires = if (expiresUtc <= 0L) 0L else expiresUtc.toExpirySeconds()
    val prefix = if (httpOnly) "#HttpOnly_" else ""
    return "$prefix$host\t$includeSubdomains\t$path\t${secure.asNetscapeFlag()}\t$expires\t$name\t$value"
}

private fun Boolean.asNetscapeFlag() = if (this) "TRUE" else "FALSE"

private fun Context.chromiumCookieDatabase(): File? {
    val root = File(dataDir, "app_webview")
    return listOf(
        File(root, "Default/Cookies"),
        File(root, "Default/Network/Cookies"),
    ).firstOrNull { it.isFile }
}

private data class StoredCookie(
    val host: String,
    val name: String,
    val value: String,
    val path: String,
    val expiresUtc: Long,
    val secure: Boolean,
    val httpOnly: Boolean,
)
